/**
 * The Battle
 * ----------
 * The three hundred shatter jars, light torches, blow trumpets, and shout for the Lord and for Gideon; the host turns on itself. Stage: the midnight camp erupting in flame and trumpet, torchlight sweeping the tents, panic in the dark; the valley blazing like a battlefield of light.
 *
 * Palette 0x1a0808 → 0x0a0502 · light: ember · hero: horn
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./gideon-kit.js.
 */

import { THREE, createScene, tent, firepit, flame, army, horn, person } from './gideon-kit.js';

const BG = 0x1a0808;
const GROUND = 0x0a0502;

export function build(group) {
    const W = createScene(group, { seed: 207431985, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x0a0502, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* camp: a circle of tents, smoke rising */
    tent(W, group, -5.6, 0, -0.8, 1.30, 0x8a6a44, W.r() * 6);
    tent(W, group, -11.0, 0, -7.5, 1.04, 0xc8b088, W.r() * 6);
    tent(W, group, 16.5, 0, -21.5, 0.92, 0xc8b088, W.r() * 6);
    tent(W, group, 7.6, 0, -24.7, 1.15, 0xd8c8a0, W.r() * 6);
    tent(W, group, 28.0, 0, -18.5, 1.39, 0xa8704a, W.r() * 6);
    firepit(W, group, -5.1, 0, -0.8, 1.0);

    /* fire: the burning mark */
    flame(W, group, 2.9, 0, -4.1, 1.1);
    W.point(0xff8a30, 2.0, 55, 0, 3, 0, 0.35);

    /* army: shields and spears in rank */
    army(W, group, 12.2, 22.7, 8, { shields: [0x110505, 0x090502, 0x8a7a2a, 0x3a5a8a] });

    /* hero: the horn */
    horn(W, group, 0, 1.2, 0, 1.3, { color: 0x170707 });
    W.disc([0, 4, -10], 4, 0x220a0a, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x1a0808, ry: 0.17, s: 1.11 });

    return W.finish();
}

export default { build };
